--装备TID->风格数组
fashion_config.FashionStyleIndex = {}

function fashion_config:GetFashionState()
    local ret_table = {}
	local style_table = fashion_config.FashionStyle
    ret_table[#ret_table + 1] = #style_table
    for i=1,#style_table do
        ret_table[#ret_table + 1] = #style_table[i]
        for k,v in pairs(style_table[i]) do
            ret_table[#ret_table + 1] = v
        end
    end
    return unpack(ret_table)
end

function fashion_config:InitStyleIndex()
	local style_table = fashion_config.FashionStyle
	local res_table = fashion_config.FashionStyleIndex
	for i=1,#style_table do
		for j=1,#style_table[i] do
			local k = style_table[i][j]
			if res_table[k] == nil then
				res_table[k] = {i}
			else
				table.insert(res_table[k], i)
			end
		end
	end
end

function fashion_config:GetStylesByTid(tid)
	if fashion_config.FashionStyleIndex[tid] then
		return unpack(fashion_config.FashionStyleIndex[tid])
	else
		return unpack({})
	end
end

fashion_config:InitStyleIndex()
